/bin/bash -lc "node --input-type=module <<'NODE'
const base = 'http://localhost:3100'
const cases = [
  ['/', 200, 'Welcome to My Blog'],
  ['/blog', 200, 'All Blog Posts'],
  ['/blog/1', 200, 'Comments (5)'],
  ['/blog/11', 200, 'Comments (5)'],
  ['/blog/999', 404, '404 - Page Not Found'],
  ['/missing', 404, '404 - Page Not Found'],
]
for (const [path, expectedStatus, expectedText] of cases) {
  const response = await fetch("'`${base}${path}`)
  const html = await response.text()
  if (response.status !== expectedStatus || !html.includes(expectedText)) {
    throw new Error(`${path}: got ${response.status}, expected ${expectedStatus} and ${expectedText}`)
  }
  console.log(`${path}: ${response.status}`)
}
const requests = [
  ['"'/api/posts', 'GET', undefined, 200],
  ['/api/posts', 'POST', { title: 'Test', content: 'Body' }, 201],
  ['/api/posts', 'POST', { title: '' }, 400],
  ['/api/posts', 'PUT', {}, 405],
  ['/api/posts/2', 'GET', undefined, 200],
  ['/api/posts/2', 'PUT', { title: 'Updated', content: 'Body' }, 200],
  ['/api/posts/2', 'DELETE', undefined, 200],
  ['/api/posts/2', 'POST', {}, 405],
]
for (const [path, method, body, expectedStatus] of requests) {
  const response = await fetch("'`${base}${path}`, {
    method,
    ...(body === undefined ? {} : { headers: { '"'content-type': 'application/json' }, body: JSON.stringify(body) }),
  })
  if (response.status "'!== expectedStatus) {
    throw new Error(`${method} ${path}: got ${response.status}, expected ${expectedStatus}`)
  }
  console.log(`${method} ${path}: ${response.status}`)
}
NODE'

