/bin/bash -lc "node --input-type=module <<'NODE'
for (const path of ['/', '/blog', '/blog/1', '/blog/999', '/missing']) {
  const response = await fetch("'`http://localhost:3100${path}`)
  const html = await response.text()
  const title = html.match(/<title>(.*?)<'"\\/title>/)?.[1]
  const description = html.match(/<meta name=\"description\" content=\"(.*?)\"\\/>/)?.[1]
  console.log("'`${path} ${response.status} ${JSON.stringify({ title, description })}`)
}
